class FilterIteratorResourceEqualityTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI SUBJECT = iri("s");
	private static final IRI FIRST = iri("a");
	private static final IRI WANTED = iri("b");
	private static final IRI OPTIONAL_PREDICATE = iri("c");
	private static final IRI REQUIRED_PREDICATE = iri("d");

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void equalityDoesNotCreateRowsThroughOptional(boolean reverseEquality) {
		assertThat(evaluate(optionalThenRequired(), matchingOptionalData(), reverseEquality)).isEmpty();
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void equalityDoesNotCreateRowsThroughOptionalInsideUnion(boolean reverseEquality) {
		TupleExpr argument = new Union(optionalThenRequired(),
				new Union(optionalThenRequired(), optionalThenRequired()));

		// Every nonempty branch assures y, so this must still check the nested OPTIONAL's safety.
		assertThat(argument.getAssuredBindingNames()).contains("y");
		assertThat(evaluate(argument, matchingOptionalData(), reverseEquality)).isEmpty();
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void equalityDoesNotCreateRowsThroughNestedOptional(boolean reverseEquality) {
		LeftJoin optional = new LeftJoin(partiallyBoundUnion(), pattern(SUBJECT, OPTIONAL_PREDICATE, "y"));
		LeftJoin enclosingOptional = new LeftJoin(optional, pattern(SUBJECT, iri("extra"), "extra"));
		TupleExpr argument = new Join(enclosingOptional, pattern(SUBJECT, REQUIRED_PREDICATE, "y"));

		assertThat(evaluate(argument, matchingOptionalData(), reverseEquality)).isEmpty();
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void unmatchedOptionalStillPreservesEveryLegitimateRow(boolean reverseEquality) {
		Model model = baseData();
		model.add(WANTED, WANTED, VF.createLiteral(2));

		List<BindingSet> rows = evaluate(optionalThenRequired(), model, reverseEquality);

		assertThat(rows).hasSize(2);
		assertThat(rows).allSatisfy(row -> {
			assertThat(row.getValue("y")).isEqualTo(WANTED);
			assertThat(row.getValue("wanted")).isEqualTo(WANTED);
		});
		assertThat(rows).extracting(row -> row.getValue("z"))
				.containsExactlyInAnyOrder(VF.createLiteral(1), VF.createLiteral(2));
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void positiveJoinsAndUnionsStillPrebindResourceEquality(boolean reverseEquality) {
		TupleExpr argument = new Join(
				new Union(pattern(SUBJECT, REQUIRED_PREDICATE, "y"), wantedPattern()),
				pattern(SUBJECT, REQUIRED_PREDICATE, "y"));
		List<Value> requiredLookupObjects = new ArrayList<>();
		TripleSource source = tripleSource(baseData(), requiredLookupObjects);

		List<BindingSet> rows = evaluate(argument, source, reverseEquality);

		assertThat(rows).hasSize(2);
		assertThat(rows).allSatisfy(row -> assertThat(row.getValue("y")).isEqualTo(WANTED));
		assertThat(requiredLookupObjects).isNotEmpty().containsOnly(WANTED);
	}

	private static TupleExpr optionalThenRequired() {
		return new Join(
				new LeftJoin(partiallyBoundUnion(), pattern(SUBJECT, OPTIONAL_PREDICATE, "y")),
				pattern(SUBJECT, REQUIRED_PREDICATE, "y"));
	}

	private static TupleExpr partiallyBoundUnion() {
		return new Union(pattern(SUBJECT, FIRST, "y"), wantedPattern());
	}

	private static StatementPattern wantedPattern() {
		return new StatementPattern(Var.of("wanted"), constant(WANTED), Var.of("z"));
	}

	private static StatementPattern pattern(IRI subject, IRI predicate, String objectName) {
		return new StatementPattern(constant(subject), constant(predicate), Var.of(objectName));
	}

	private static Var constant(IRI value) {
		return Var.of("_const_" + value.getLocalName(), value, true, true);
	}

	private static Model matchingOptionalData() {
		Model model = baseData();
		model.add(SUBJECT, OPTIONAL_PREDICATE, FIRST);
		return model;
	}

	private static Model baseData() {
		Model model = new LinkedHashModel();
		model.add(SUBJECT, FIRST, FIRST);
		model.add(SUBJECT, REQUIRED_PREDICATE, WANTED);
		model.add(WANTED, WANTED, VF.createLiteral(1));
		return model;
	}

	private static List<BindingSet> evaluate(TupleExpr argument, Model model, boolean reverseEquality) {
		return evaluate(argument, tripleSource(model, new ArrayList<>()), reverseEquality);
	}

	private static List<BindingSet> evaluate(TupleExpr argument, TripleSource source, boolean reverseEquality) {
		Compare condition = reverseEquality
				? new Compare(Var.of("wanted"), Var.of("y"), CompareOp.EQ)
				: new Compare(Var.of("y"), Var.of("wanted"), CompareOp.EQ);
		Filter filter = new Filter(argument, condition);
		QueryBindingSet bindings = new QueryBindingSet();
		bindings.addBinding("wanted", WANTED);
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(source, null);
		List<BindingSet> rows = new ArrayList<>();
		try (CloseableIteration<BindingSet> iteration = strategy.precompile(filter).evaluate(bindings)) {
			iteration.forEachRemaining(rows::add);
		}
		return rows;
	}

	private static TripleSource tripleSource(Model model, List<Value> requiredLookupObjects) {
		return new TripleSource() {
			@Override
			public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate,
					Value object, Resource... contexts) {
				if (REQUIRED_PREDICATE.equals(predicate)) {
					requiredLookupObjects.add(object);
				}
				return new CloseableIteratorIteration<>(
						model.getStatements(subject, predicate, object, contexts).iterator());
			}

			@Override
			public ValueFactory getValueFactory() {
				return VF;
			}
		};
	}

	private static IRI iri(String localName) {
		return VF.createIRI("urn:equality:", localName);
	}
}
